// name must be valid DNS subdomains. The function never panics, even on adversarial input, and
// every returned error has a non-empty Field and Detail.
func validatePolicyNames(context *annotationValidationContext) field.ErrorList {
	allErrs := field.ErrorList{}

	for _, entry := range strings.Split(context.value, commaDelimiter) {
		policy := strings.TrimSpace(entry)
		if policy == "" {
			allErrs = append(allErrs, field.Invalid(context.fieldPath, entry, "policy name cannot be empty"))
			continue
		}

		name := policy
		if idx := strings.Index(policy, "/"); idx != -1 {
			namespace := strings.TrimSpace(policy[:idx])
			name = strings.TrimSpace(policy[idx+1:])

			if namespace == "" {
				allErrs = append(allErrs, field.Invalid(context.fieldPath, entry, "policy namespace cannot be empty"))
				continue
			}
			for _, msg := range validation.IsDNS1123Subdomain(namespace) {
				allErrs = append(allErrs, field.Invalid(context.fieldPath, namespace, fmt.Sprintf("policy namespace must be a valid DNS subdomain: %s", msg)))
			}
		}

		if name == "" {
			allErrs = append(allErrs, field.Invalid(context.fieldPath, entry, "policy name cannot be empty"))
			continue
		}
		for _, msg := range validation.IsDNS1123Subdomain(name) {
			allErrs = append(allErrs, field.Invalid(context.fieldPath, name, fmt.Sprintf("policy name must be a valid DNS subdomain: %s", msg)))
		}
	}

